def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Initialize counters
    my_score = 0
    opp_score = 0
    recent_opp_defects = 0

    # We only need history from max(0, n-20) to n for recent stats, 
    # but full score calculation requires all. Let's optimize by calculating scores in one pass.

    start_window = max(0, n - 10)

    for i in range(n):
        me, opp = history[i]

        # Calculate payoff
        if me == 'C':
            if opp == 'C':
                my_score += 3
                opp_score += 3
            else:
                my_score += 0
                opp_score += 5
        else:
            if opp == 'C':
                my_score += 5
                opp_score += 0
            else:
                my_score += 1
                opp_score += 1

        # Count recent opponent defects (last 10 rounds including current)
        if i >= start_window:
            if opp == 'D':
                recent_opp_defects += 1

    last_me, last_opp = history[-1]

    # End-game strategy (rounds 90+)
    if n >= 90:
        if recent_opp_defects <= 2:
            return 'C'
        elif recent_opp_defects >= 6:
            return 'D'
        else:
            # Intermediate case, mirror last move or slight randomness
            if last_opp == 'C':
                return 'C'
            return 'D'

    # Standard Strategy

    # If opponent just defected
    if last_opp == 'D':
        # Check if they have been defecting frequently recently
        if recent_opp_defects >= 5:
            # Sustained aggression -> Defect back
            return 'D'
        else:
            # Isolated defection or noise -> Forgiveness with probability
            if rng.random() < 0.4:
                return 'C'
            return 'D'

    # If opponent just cooperated
    if last_opp == 'C':
        # If we were defecting and they stayed cooperative, we might want to continue exploiting
        # But generally reciprocate C with C unless they are too nice? No, exploit nice players?
        # Payoff: CD=5 vs CC=3. Exploiting is better for own score.
        # However, stability matters.

        # If I was C last round, stick to C
        if last_me == 'C':
            return 'C'

        # If I was D last round, and they still played C:
        # They might be a "Sucker" or "Generous Tit-for-Tat".
        # If they forgave my previous D, maybe keep pressuring?
        # But if they punish next time, it gets messy.

        # Simple heuristic: Return to cooperation to build trust/score, but occasionally probe.
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'
